def is_composite(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

F_values = []
F = 2
while len(F_values) < 50:
    if is_composite(F - 1) and is_composite(F + 1):
        F_values.append(F)
    F += 1

print(F_values)
print(F_values[-1])

